MOD = 10**9 + 7

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

# Compute the LCM of numbers from 1 to 9
lcm_value = 1
for i in range(1, 10):
    lcm_value = lcm(lcm_value, i)

# Function to find the number of ways
def find_ways(P, T):
    n = len(T)
    m = len(P)

    # dp[mask] will store the number of ways to achieve the product of positions represented by the mask
    dp = [0] * (1 << m)
    dp[0] = 1  # There's one way to achieve the product 0 (no positions)

    for i in range(n):
        new_dp = dp.copy()
        for mask in range(1 << m):
            if dp[mask]:
                pos_product = 0
                for j in range(m):
                    if mask & (1 << j):
                        pos_product += (i - j)
                if pos_product % lcm_value == 0:
                    new_dp[mask] += dp[mask]
                    new_dp[mask] %= MOD
                    for j in range(m):
                        if not (mask & (1 << j)):
                            new_dp[mask | (1 << j)] += dp[mask]
                            new_dp[mask | (1 << j)] %= MOD
        dp = new_dp

    return dp[(1 << m) - 1]

# Read input
P = input().strip()
T = input().strip()

# Find and print the number of ways
print(find_ways(P, T))
